package com.hbm.machine.rockmill;
import com.google.gson.*;
import com.hbm.recipe.generic.*;
import com.mojang.logging.LogUtils;
import java.nio.file.*;
import java.util.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.EventPriority;
import net.neoforged.fml.loading.FMLPaths;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.OnDatapackSyncEvent;
import net.neoforged.neoforge.event.server.ServerAboutToStartEvent;
/** Exact original GenericRecipes replacement grammar, auto-switch order and full weighted outputs. */
public final class RockMillRecipeConfig {
 private static final Map<RecipeManager,Map<ResourceLocation,RecipeHolder<?>>> INSTALLED=new WeakHashMap<>();private static final Map<String,String> ALIASES=new LinkedHashMap<>();private static final List<String> UNRESOLVED=new ArrayList<>();
 public static void register(){try(var stream=RockMillRecipeConfig.class.getResourceAsStream("/hbm/machine-rockmill64-item-aliases.json")){if(stream==null)throw new IllegalStateException("Missing original rock mill item aliases");JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject().entrySet().forEach(e->ALIASES.put(e.getKey(),e.getValue().getAsString()));}catch(java.io.IOException error){throw new IllegalStateException(error);}NeoForge.EVENT_BUS.addListener((ServerAboutToStartEvent e)->install(e.getServer()));NeoForge.EVENT_BUS.addListener(EventPriority.LOWEST,(OnDatapackSyncEvent e)->{var server=e.getPlayerList().getServer();if(e.getPlayer()==null||!INSTALLED.containsKey(server.getRecipeManager()))install(server);});}
 public static List<RockMillRecipe> recipes(RecipeManager manager){return manager.getAllRecipesFor(RockMillContent.TYPE.get()).stream().map(RecipeHolder::value).sorted(Comparator.comparingInt(r->r.data().order())).toList();}
 public static List<String> unresolved(){return List.copyOf(UNRESOLVED);}
    public static void reload(MinecraftServer server) { install(server); }
 private static void install(MinecraftServer server){var manager=server.getRecipeManager();var previous=INSTALLED.getOrDefault(manager,Map.of());var merged=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();for(var holder:manager.getOrderedRecipes())if(previous.get(holder.id())!=holder)merged.put(holder.id(),holder);var additions=new LinkedHashMap<ResourceLocation,RecipeHolder<?>>();UNRESOLVED.clear();Path dir=FMLPaths.CONFIGDIR.get().resolve("hbmRecipes"),active=dir.resolve("hbmRockMill.json");try{Files.createDirectories(dir);boolean custom=Files.isRegularFile(active);JsonObject root;if(custom){merged.values().removeIf(h->h.value().getType()==RockMillContent.TYPE.get());try(var reader=Files.newBufferedReader(active)){root=JsonParser.parseReader(reader).getAsJsonObject();}}else{try(var stream=RockMillRecipeConfig.class.getResourceAsStream("/hbm/machine-rockmill64-source-recipes.json")){if(stream==null)throw new IllegalStateException("Missing original rock mill defaults");root=JsonParser.parseReader(new java.io.InputStreamReader(stream,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();}}var template=new JsonObject();var exported=new JsonArray();template.add("recipes",exported);int order=0;var names=new HashSet<String>();for(var value:root.getAsJsonArray("recipes")){String label="row "+order;try{var row=value.getAsJsonObject();var d=GenericRecipeConfigCodec.read(row,server.registryAccess(),ALIASES);label=d.name();if(!names.add(d.name()))throw new IllegalArgumentException("Duplicate original recipe name "+d.name());ItemStack icon=d.icon();if(!custom&&row.has("sourceIconToFirstIngredient")&&row.get("sourceIconToFirstIngredient").getAsBoolean()&&!d.inputItems().isEmpty()){var examples=d.inputItems().getFirst().examples();if(!examples.isEmpty())icon=examples.getFirst().copy();}d=new GenericRecipeData(d.name(),d.duration(),d.power(),d.inputItems(),d.inputFluids(),d.outputItems(),d.outputFluids(),d.pools(),d.group(),icon,d.named(),d.nameWrapper(),order);var id=ResourceLocation.fromNamespaceAndPath("hbm","rockmill/"+(custom?"config/":"default/")+order);additions.put(id,new RecipeHolder<>(id,new RockMillRecipe(d)));var export=GenericRecipeConfigCodec.write(d);if(!custom&&row.has("sourceIconToFirstIngredient"))export.remove("icon");exported.add(export);}catch(Exception error){UNRESOLVED.add(label+": "+error.getMessage());}order++;}if(!custom)Files.writeString(dir.resolve("_hbmRockMill.json"),new GsonBuilder().setPrettyPrinting().create().toJson(template)+"\n");}catch(Exception error){LogUtils.getLogger().error("Cannot load original rock mill recipes",error);}additions.forEach(merged::put);manager.replaceRecipes(merged.values());INSTALLED.put(manager,additions);Blueprints.registerRecipes(ResourceLocation.fromNamespaceAndPath("hbm","rockmill"),recipes(manager));for(var error:UNRESOLVED)LogUtils.getLogger().warn("Unbound original rock mill recipe: {}",error);}
 private RockMillRecipeConfig(){}
}
